<?php
include('../config.php');
require_once __DIR__.'/../base/GameEmailPolicy.class.php';
$pagegen=new page_gen();$pagegen->round_to=4;$pagegen->start();$s=new Game();if(!$s->loggedIn||!isset($_GET['time'])){header('Location: ../index.php');exit;}$db=$s->db_link;$uid=(int)$_SESSION['userid'];$tab=(string)($_REQUEST['tab']??'inbox');$id=(int)($_REQUEST['id']??0);$notice='';$error='';
$db->query("CREATE TABLE IF NOT EXISTS game_email_messages (email_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,from_uid INT NULL,from_address VARCHAR(190) NOT NULL,to_uid INT NULL,to_address VARCHAR(190) NOT NULL,subject VARCHAR(190) NOT NULL,body TEXT NOT NULL,email_type VARCHAR(16) NOT NULL DEFAULT 'player',is_read TINYINT(1) NOT NULL DEFAULT 0,is_deleted TINYINT(1) NOT NULL DEFAULT 0,delivery_status VARCHAR(16) NOT NULL DEFAULT 'inbox',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,sent_at DATETIME NULL,KEY idx_game_email_recipient(to_uid,is_deleted,created_at),KEY idx_game_email_sender(from_uid,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
if($_SERVER['REQUEST_METHOD']==='POST'){$action=(string)($_POST['email_action']??'');if($action==='send'){$to=(int)($_POST['to_uid']??0);$subject=GameEmailPolicy::cleanSubject((string)($_POST['subject']??''));$body=GameEmailPolicy::cleanBody((string)($_POST['body']??''));$recipient=$db->query("SELECT uname,email FROM users WHERE uid=$to LIMIT 1");$r=$recipient?$recipient->fetch_assoc():null;if(!$r||$to===$uid||$subject===''||$body==='')$error='Choose a valid recipient and provide a subject and message body.';else{$from=$db->query("SELECT uname,email FROM users WHERE uid=$uid LIMIT 1");$f=$from?$from->fetch_assoc():null;$fromAddress=GameEmailPolicy::validAddress((string)($f['email']??''))?$f['email']:('player'.$uid.'@universecivilization.game');$toAddress=GameEmailPolicy::validAddress((string)($r['email']??''))?$r['email']:('player'.$to.'@universecivilization.game');$stmt=$db->prepare('INSERT INTO game_email_messages(from_uid,from_address,to_uid,to_address,subject,body,email_type,delivery_status,sent_at) VALUES(?,?,?,?,?,?,\'player\',\'inbox\',NOW())');if($stmt){$stmt->bind_param('iissss',$uid,$fromAddress,$to,$toAddress,$subject,$body);if($stmt->execute()){$notice='Email sent through the game mail network.';$tab='sent';}else$error='Email delivery failed.';}else$error='Email service unavailable.';}}elseif($action==='read'){$db->query("UPDATE game_email_messages SET is_read=1 WHERE email_id=$id AND to_uid=$uid LIMIT 1");$tab='read';}elseif($action==='delete'){$db->query("UPDATE game_email_messages SET is_deleted=1 WHERE email_id=$id AND (to_uid=$uid OR from_uid=$uid) LIMIT 1");$notice='Email deleted.';$tab='inbox';}}
$rootAddress=GameEmailPolicy::ROOT_ADDRESS;$unreadQ=$db->query("SELECT COUNT(*) c FROM game_email_messages WHERE to_uid=$uid AND is_read=0 AND is_deleted=0");$unread=(int)($unreadQ?$unreadQ->fetch_assoc()['c']:0);$inbox=$db->query("SELECT e.*,u.uname sender_name FROM game_email_messages e LEFT JOIN users u ON u.uid=e.from_uid WHERE e.to_uid=$uid AND e.is_deleted=0 ORDER BY e.email_id DESC LIMIT 100");$sent=$db->query("SELECT e.*,u.uname recipient_name FROM game_email_messages e LEFT JOIN users u ON u.uid=e.to_uid WHERE e.from_uid=$uid AND e.is_deleted=0 ORDER BY e.email_id DESC LIMIT 100");
echo '<div class="comm-shell"><div class="page-hub-head"><span class="rts-kicker">UNIVERSE CIVILIZATION // EMAIL NETWORK</span><h3>Game Email</h3><p>Secure in-game mail for commanders, system notices, and root administration. Root system address: '.htmlspecialchars($rootAddress,ENT_QUOTES,'UTF-8').'</p></div>';if($notice)echo '<div class="comm-alert">'.htmlspecialchars($notice,ENT_QUOTES,'UTF-8').'</div>';if($error)echo '<div class="comm-alert comm-error">'.htmlspecialchars($error,ENT_QUOTES,'UTF-8').'</div>';echo '<section class="comm-card"><p><a class="comm-btn" href="javascript:void(0)" onclick="sendData(\'email\',\'get\',\'mainDisplay\',\'inbox\');return false">Inbox '.($unread?'('.$unread.' unread)':'').'</a> <a class="comm-btn" href="javascript:void(0)" onclick="sendData(\'email\',\'get\',\'mainDisplay\',\'sent\');return false">Sent</a> <a class="comm-btn" href="javascript:void(0)" onclick="sendData(\'email\',\'get\',\'mainDisplay\',\'compose\');return false">Compose</a></p>';
if($tab==='compose'){echo '<form method="post" class="admin-form-grid" action="/modules/email.php?time='.time().'&tab=compose"><input type="hidden" name="email_action" value="send"><label>Recipient UID<input type="number" name="to_uid" min="1" required></label><label>Subject<input name="subject" maxlength="190" required></label><label>Message<textarea name="body" rows="10" maxlength="20000" required></textarea></label><button class="comm-btn">Send Email</button></form>';}elseif($tab==='read'&&$id>0){$q=$db->query("SELECT e.*,u.uname sender_name FROM game_email_messages e LEFT JOIN users u ON u.uid=e.from_uid WHERE e.email_id=$id AND (e.to_uid=$uid OR e.from_uid=$uid) AND e.is_deleted=0 LIMIT 1");$m=$q?$q->fetch_assoc():null;if($m)echo '<h4>'.htmlspecialchars($m['subject'],ENT_QUOTES,'UTF-8').'</h4><p>From: '.htmlspecialchars($m['from_address'],ENT_QUOTES,'UTF-8').' · To: '.htmlspecialchars($m['to_address'],ENT_QUOTES,'UTF-8').'</p><div class="comm-card">'.nl2br(htmlspecialchars($m['body'],ENT_QUOTES,'UTF-8')).'</div>';else echo '<p>Email not found.</p>';}elseif($tab==='sent'){echo '<div class="admin-table-wrap"><table><tr><th>To</th><th>Subject</th><th>Sent</th><th>Action</th></tr>';if($sent)while($m=$sent->fetch_assoc())echo '<tr><td>'.htmlspecialchars($m['recipient_name']?:$m['to_address'],ENT_QUOTES,'UTF-8').'</td><td>'.htmlspecialchars($m['subject'],ENT_QUOTES,'UTF-8').'</td><td>'.htmlspecialchars($m['created_at'],ENT_QUOTES,'UTF-8').'</td><td><form method="post"><input type="hidden" name="email_action" value="delete"><input type="hidden" name="id" value="'.(int)$m['email_id'].'"><button class="comm-btn">Delete</button></form></td></tr>';echo '</table></div>';}else{echo '<div class="admin-table-wrap"><table><tr><th>Status</th><th>From</th><th>Subject</th><th>Received</th><th>Action</th></tr>';if($inbox)while($m=$inbox->fetch_assoc())echo '<tr><td>'.((int)$m['is_read']?'Read':'Unread').'</td><td>'.htmlspecialchars($m['sender_name']?:$m['from_address'],ENT_QUOTES,'UTF-8').'</td><td><form method="post" style="display:inline"><input type="hidden" name="email_action" value="read"><input type="hidden" name="id" value="'.(int)$m['email_id'].'"><button class="comm-btn">'.htmlspecialchars($m['subject'],ENT_QUOTES,'UTF-8').'</button></form></td><td>'.htmlspecialchars($m['created_at'],ENT_QUOTES,'UTF-8').'</td><td><form method="post"><input type="hidden" name="email_action" value="delete"><input type="hidden" name="id" value="'.(int)$m['email_id'].'"><button class="comm-btn">Delete</button></form></td></tr>';echo '</table></div>';}echo '</section></div>';$pagegen->stop();print('page generation time: '.$pagegen->gen()); ?>
